import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ──────────────────────────────────────────────────────────────────────────
  // 1. STAGE: backdrop gradient plane
  // ──────────────────────────────────────────────────────────────────────────
  const backdrop = new THREE.Mesh(
    new THREE.PlaneGeometry(7, 6),
    new MeshBasicNodeMaterial({
      color: config.intent?.visualSpec?.colors?.surface ?? '#0b0b10',
    })
  );
  backdrop.position.z = -2.5;
  backdrop.castShadow = false;
  backdrop.receiveShadow = false;

  // ──────────────────────────────────────────────────────────────────────────
  // 2. SPRITE: atlas-region textured plane (billboard toward camera)
  // ──────────────────────────────────────────────────────────────────────────
  const aspectRatio = 512 / 320; // atlas region aspect ratio
  const spriteGeometry = new THREE.PlaneGeometry(aspectRatio * 0.8, 0.8);

  // Load ceramic-grain texture
  const texturePromise = config.imageUrl 
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  let spriteMesh = null;
  texturePromise.then((texture) => {
    if (texture) {
      // Atlas region: (0, 0, 512, 320) in a full atlas
      // Assuming full atlas is 2048x2048 (common), normalize the rect
      const atlasWidth = 2048;
      const atlasHeight = 2048;
      const srcX = 0;
      const srcY = 0;
      const srcW = 512;
      const srcH = 320;

      const minU = srcX / atlasWidth;
      const maxU = (srcX + srcW) / atlasWidth;
      const minV = srcY / atlasHeight;
      const maxV = (srcY + srcH) / atlasHeight;

      // Apply UV offset to the spriteGeometry
      const uvAttribute = spriteGeometry.attributes.uv;
      for (let i = 0; i < uvAttribute.count; i++) {
        const u = uvAttribute.getX(i);
        const v = uvAttribute.getY(i);
        uvAttribute.setXY(i, minU + u * (maxU - minU), minV + v * (maxV - minV));
      }
      uvAttribute.needsUpdate = true;

      // Create sprite material with texture
      const spriteMaterial = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        depthTest: true,
        depthWrite: false,
        side: THREE.DoubleSide,
      });

      spriteMesh = new THREE.Mesh(spriteGeometry, spriteMaterial);
      spriteMesh.position.copy(config.scenePosition || new THREE.Vector3(0, 1, 0.06));
      spriteMesh.castShadow = false;
      spriteMesh.receiveShadow = false;

      // Billboard toward camera (look at camera center)
      spriteMesh.lookAt(0, 0, 5);

      group.add(spriteMesh);
    }
  });

  // ──────────────────────────────────────────────────────────────────────────
  // 3. TEXT: headline label "Pricing 2"
  // ──────────────────────────────────────────────────────────────────────────
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textContent.find((item) => item.role === 'headline') || 
                   textContent[0] || 
                   { text: 'Pricing 2', role: 'headline', typography: { fontSize: 39 } };

  const textMesh = ctx.fontAtlas.createText(String(textItem.text), {
    fontSize: textItem.typography?.fontSize ?? 39,
    color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0,
  });
  textMesh.position.set(0, 0, 0.1);
  textMesh.castShadow = false;
  textMesh.receiveShadow = false;

  // ──────────────────────────────────────────────────────────────────────────
  // 4. COMPOSITION: root group
  // ──────────────────────────────────────────────────────────────────────────
  const group = new THREE.Group();
  group.add(backdrop);
  group.add(textMesh);

  // ──────────────────────────────────────────────────────────────────────────
  // 5. CLEANUP
  // ──────────────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    spriteGeometry.dispose();
    if (spriteMesh?.material) {
      spriteMesh.material.dispose();
      if (spriteMesh.material.map) {
        spriteMesh.material.map.dispose();
      }
    }
    backdrop.geometry.dispose();
    backdrop.material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
